            "«Тяжёлое основание — лучше?» Здесь отзывы противоречат друг другу: один игрок считает экземпляр 93 г немного слишком быстрым, другой пишет, что более тяжёлые экземпляры играют лучше и меньше вибрируют, а ещё один доволен весом 96 г. Надёжный вывод один: разброс веса у Apolonia заметный (в отзывах — от 89 до 96 г), поэтому вес стоит проверять до поклейки — особенно если на форхенд идёт Zyre 03 2,7 мм.",
