          ru: [
            "На официальной странице Apolonia ZLC Butterfly называет двух игроков: португальца Тиагу Аполонию, в честь которого названо основание, и немца Томаса Шмидбергера — чемпиона мира 2022 года среди параспортсменов в классе 3 и серебряного призёра Паралимпиад 2012 и 2016 годов. Сетап каждого взят с его страницы в Butterfly, с датой, на которую он там указан.",
            "Третья — американка Салли Мойланд, лучшее место которой в мировом рейтинге — 65-е (июль 2026 года); её сетап приводит японский справочник tabletennis-reference без даты. Ещё нескольких игроков, которых этот справочник связывает с Apolonia ZLC, мы в таблицу не включили: либо их данные устарели, либо официальная страница Butterfly указывает другое основание. Интересная деталь: Софья Полканова играет на Innerforce Layer ZLC — основании с теми же официальными характеристиками — и тоже с Dignics 05 на обеих сторонах.",
          ],
