            "Новичкам её не советуем: это всё ещё быстрое карбоновое основание, на котором ошибки в технике превращаются в длинные мячи. Тем, кому не хватает скорости, стоит смотреть на outer-основания, а тем, кому Apolonia кажется жёсткой, — на inner-ALC с более низкой вибрацией.",
