          name: { ua: "Butterfly Apolonia ZLC", ru: "Butterfly Apolonia ZLC" },
          verdict: { ua: "Inner-ZLC з реакцією 10,5: швидкість карбону з вищою дугою, ніж у Viscaria, — для впевненого аматора й вище.", ru: "Inner-ZLC с реакцией 10,5: скорость карбона с более высокой дугой, чем у Viscaria, — для уверенного любителя и выше." },
          alt: { ua: "Основа Butterfly Apolonia ZLC з карбоном ZLC ближче до ядра", ru: "Основание Butterfly Apolonia ZLC с карбоном ZLC ближе к ядру" },
